#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddTrendWnd(DefineTegs)  {  RECT rect;  STegObj obj[] =    {    { 'R', "rect", &rect },    { 'E', "rc"  , &rect },    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  ASSERT(FALSE);  ::SendMsg(def.m_queue.hWnd,QUEUE_TREND_W,(LPARAM)&rect);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~typedef struct : public SPROLOZ  {  HWND  hWnd;  float dScale;  bool  bDestroy;  bool  bHistory;  } Queue_AlarmWnd;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearAlarmWnd(SQueue& q,void* s)  {  Queue_AlarmWnd* p = (Queue_AlarmWnd*)s;  if ( p->bDestroy )    if ( ::IsWindow( p->hWnd ) )      ::DestroyWindow( p->hWnd );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintAlarmWnd(DefinePaint)  {  QueueP(Queue_AlarmWnd);  if ( p->dScale != q.setScale )    {    p->dScale = q.setScale;    ::PostMessage(p->hWnd,nPressQueue,QUEUE_SCALE,(LPARAM)(&p->dScale));    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddAlarmWnd(DefineTegs)  {  AddQueueEx(Queue_AlarmWnd);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintAlarmWnd;  p->clear = &ClearAlarmWnd;  p->bHistory = false;  RECT rect;  STegObj obj[] =    {    { 'R', "rect"   , &rect },    { 'E', "rc"     , &rect },    { 'L', "destroy", &p->bDestroy },    { 'L', "history", &p->bHistory },    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //ASSERT(FALSE);  p->dScale = 1.0;  if(AOP_TOBOLSK == Version)  {      QUEUE_ALARM_W_STRUCT qal={{0}, 0x55556666};      qal.rect=rect;      if(p->bHistory)         {        qal.Type=A_History;        qal.bHeader=true;        }      else{          qal.Type=A_Alarms;          qal.bHeader=false;          }      p->hWnd = (HWND)::SendMsg(def.m_queue.hWnd,QUEUE_ALARM_W,(LPARAM)&qal);  }  else  p->hWnd = (HWND)::SendMsg(def.m_queue.hWnd,QUEUE_ALARM_W,(LPARAM)&rect);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddSergejC(DefineTegs)  {  def.ms_bAddQueue = false;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddSergejD(DefineTegs)  {  def.ms_bAddQueue = true;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~